package cn.safetyledger.app.sync;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class HttpSyncProvider implements SyncProvider{private final String providerType;public HttpSyncProvider(String t){providerType=t;}public String type(){return providerType;}public ConnectionResult test(Map<String,String>c){String endpoint=c.getOrDefault("endpoint","");if(endpoint.isBlank())return new ConnectionResult(false,"请填写服务地址");try{HttpURLConnection h=(HttpURLConnection)new URL(endpoint).openConnection();h.setConnectTimeout(8000);h.setReadTimeout(8000);h.setRequestMethod("WebDAV".equals(providerType)?"OPTIONS":"HEAD");String user=c.getOrDefault("username",""),secret=c.getOrDefault("secret","");if(!user.isBlank())h.setRequestProperty("Authorization","Basic "+Base64.getEncoder().encodeToString((user+":"+secret).getBytes(StandardCharsets.UTF_8)));if(!c.getOrDefault("token","").isBlank())h.setRequestProperty("Authorization","Bearer "+c.get("token"));int code=h.getResponseCode();return new ConnectionResult(code>=200&&code<400,"HTTP "+code+(code>=200&&code<400?"，连接成功":"，服务器拒绝连接"));}catch(Exception e){return new ConnectionResult(false,e.getClass().getSimpleName()+"："+e.getMessage());}}}
